// Scrambler: a carnival ride made of maps that turn. X starts and stops the ride,
// O hops into a car (and back out), arrows turn the camera while you watch.
// Shows: map_set_pos / map_set_angle on maps with a pivot (origin), and drawing the same map
// several times in one frame: one arm map is drawn 3 times, one car map 12 times (recolored with
// pal), because map() draws the map wherever it is at that moment. mtow() turns a point on a
// placed map into a world position, so cars, riders and the ride camera follow the arms.
// maps: 0 plaza, 1 center pole, 2 arm, 3 spinner (hangs from an arm), 4 car
// vox: 0-1 rider (arms up / down). sounds: 0 bell, 1 stop, 2-5 the song (patterns 0-1)

const ARM_LEN = 9, ARM_PITCH = -0.045   // arms slope down from the top of the pole
const PIVOT_Y = 9.8                     // where the arms meet the pole
const CAR_R = 4                         // cars sit this far from the middle of each spinner
const ARM_COL = [8, 12, 11]             // car color for each arm (the car map is red, 8)
let spin = 0, speed = 0, running = true // pole angle (turns) and how fast it turns now
let riding = false, yaw = 0.6, pitch = -0.07   // yaw, pitch: the watching camera's view

function _init() {
  bg(12)
  music(0, 1000)
}

// where everything is right now. Each map is placed, then mtow() says where a point on it ended
// up in the world: the end of an arm, where each car sits on a spinner.
function ride() {
  let arms = [], cars = []
  for (let i = 0; i < 3; i++) {
    let a = spin + i / 3                            // this arm's yaw
    let b = -1.7 * spin + i * 0.1                   // spinners turn the other way, faster
    map_set_pos(2, [0, PIVOT_Y, 0]); map_set_angle(2, [ARM_PITCH, a, 0])
    let end = mtow(2, 0.5, 0.5, ARM_LEN)            // the arm's far end, in the middle of the beam
    map_set_pos(3, end); map_set_angle(3, [0, b, 0])
    arms.push({ a, end, b })
    for (let j = 0; j < 4; j++) {
      // on top of each end of the spinner's cross (its grid is 9 wide, the post at 4.5, 4.5)
      let [x, y, z] = mtow(3, 4.5 + CAR_R * sin(j / 4), 1, 4.5 + CAR_R * cos(j / 4))
      cars.push({ x, y, z, yaw: b + j / 4, col: ARM_COL[i], k: i * 4 + j })   // facing outward
    }
  }
  return { arms, cars }
}

function _update() {
  if (btnp(5)) {
    running = !running
    if (running) { sfx(0); music(0, 800) } else { sfx(1); music(-1, 1500) }
  }
  if (btnp(4)) riding = !riding
  speed += ((running ? 1 : 0) - speed) * 0.01       // spin up and down slowly
  spin += speed * 0.0035
  if (btn(0)) yaw -= 0.004
  if (btn(1)) yaw += 0.004
  if (btn(2)) pitch = max(pitch - 0.002, -0.2)
  if (btn(3)) pitch = min(pitch + 0.002, -0.01)
  // chasing lights: the bulbs use colors 23 and 10; swap them a few times a second
  let on = flr(time() * 5) % 2 == 0
  palette[23] = on ? 0xfff1e8 : 0xffa300
  palette[10] = on ? 0xffa300 : 0xfff1e8
}

function _draw() {
  let { arms, cars } = ride()

  if (riding) {
    // sit in car 0: place the car map there, then put the eyes above the back of its seat
    // (car grid: 3 x 3, middle at 1.5, open front toward +z) looking out the front, a little down
    let c = cars[0]
    map_set_pos(4, [c.x, c.y, c.z]); map_set_angle(4, [0, c.yaw, 0])
    cam_set_pos(mtow(4, 1.5, 2.9, 0.9))
    cam_set_lookat(mtow(4, 1.5, 1.2, 9.5))
  } else {
    cam_orbit([0, 4, 0], yaw, pitch, 26)
  }

  outline(0)
  map(0)                                            // the plaza never moves
  map_set_angle(1, [0, spin, 0]); map(1)            // the pole turns with the arms
  for (let r of arms) {
    map_set_pos(2, [0, PIVOT_Y, 0]); map_set_angle(2, [ARM_PITCH, r.a, 0]); map(2)
    map_set_pos(3, r.end); map_set_angle(3, [0, r.b, 0]); map(3)
  }
  for (let c of cars) {
    pal(8, c.col)
    map_set_pos(4, [c.x, c.y, c.z]); map_set_angle(4, [0, c.yaw, 0]); map(4)
    pal()
    // a rider in the back of the car, cheering with arms up every other beat
    if (riding && c.k == 0) continue                // that's you
    pal(12, [12, 8, 11, 9, 14, 10][c.k % 6])        // shirt color
    vox(flr(time() * 2 + c.k) % 2, ...mtow(4, 1.5, 1, 1.15), 0, c.yaw, 0, 1.6)   // on the seat, toward the back
    pal()
  }
  outline()

  print(running ? 'X: stop the ride' : 'X: start the ride', 4, 232, 7, 0)
  print(riding ? 'O: get off' : 'O: ride in a car', 4, 244, 7, 0)
  if (!riding) print('Arrows: look', 252 - 12 * 7, 244, 6, 0)
}
